import { flexRender } from '@tanstack/react-table';
import { assignInlineVars } from '@vanilla-extract/dynamic';
import clsx from 'clsx';
import React, { type CSSProperties } from 'react';

import { alignmentOptionsCSS } from './alignment-variant.sty.js';
import { dataTableV2HeaderCellCSS } from './DataTableV2Header.sty.js';
import {
  dataTableV2FirstColumnCSS,
  dataTableV2FirstHeaderRowCSS,
  dataTableV2LastColumnCSS,
  dataTableV2LastHeaderRowCSS,
} from './DataTableV2Rows.sty.js';
import { type StylingProps } from '../../../core/types/styling-props.js';
import { useDataTableV2 } from '../contexts/DataTableV2Context.js';
import { DATA_TABLE_V2_DEFAULT_HEADER_ALIGNMENT } from '../features/ColumnAlignment.js';
import { _UserActionsMenuWrapper } from '../features/UserActions.js';
import { type Header } from '../hooks/useTable/types.js';
import { dataTableV2HeaderRowIndexVar } from '../variables.sty.js';

interface TableHeaderCellProps extends StylingProps {
  header: Header<unknown, unknown>;
  columnIndex: number;
  rowIndex: number;
}

function TableHeaderCell(props: TableHeaderCellProps) {
  // If the header is a placeholder, do not render any content.
  if (props.header.isPlaceholder) {
    return null;
  }

  const gridPosition = props.header.getGridPosition(props.columnIndex);

  const content = flexRender(
    props.header.column.columnDef.header,
    props.header.getContext(),
  );

  return (
    // we cannot polymorph to a Menu trigger here and therefor have to
    // take the nesting because the ref would update too often which will
    // kill the measurement
    <div
      ref={props.header.getMeasureRef()}
      role="columnheader"
      data-header-row={props.rowIndex}
      data-column={props.columnIndex}
      style={
        {
          ...gridPosition,
          ...assignInlineVars({
            [dataTableV2HeaderRowIndexVar]: `${gridPosition.gridRowStart - 1}`,
          }),
        } as CSSProperties
      }
    >
      {props.header.getCanHeaderUserActions() ? (
        // eslint-disable-next-line react/jsx-pascal-case
        <_UserActionsMenuWrapper
          className={clsx(props.className)}
          actions={props.header.getHeaderUserActions()}
          column={props.header.column}
        >
          {content}
        </_UserActionsMenuWrapper>
      ) : (
        <div className={clsx(props.className)}>{content}</div>
      )}
    </div>
  );
}

export function DataTableV2Header(props: unknown): JSX.Element | null {
  const table = useDataTableV2();

  return (
    // eslint-disable-next-line react/jsx-no-useless-fragment
    <>
      {table?.getHeaderGroups().map((headerGroup, rowIndex, rows) =>
        headerGroup.headers.map((header, columnIndex, columns) => (
          <TableHeaderCell
            header={header}
            key={header.id}
            columnIndex={columnIndex}
            rowIndex={rowIndex}
            className={clsx(
              dataTableV2HeaderCellCSS({
                rowDensity: table.getVisualVariantOptions().rowDensity,
                verticalDividers:
                  table.getVisualVariantOptions().verticalDividers ||
                  table.getHeaderGroups().length > 1,
              }),
              alignmentOptionsCSS[
                header.column.columnDef.alignment ??
                  DATA_TABLE_V2_DEFAULT_HEADER_ALIGNMENT
              ],
              {
                [dataTableV2FirstColumnCSS]: columnIndex === 0,
                [dataTableV2LastColumnCSS]: columnIndex === columns.length - 1,
                [dataTableV2FirstHeaderRowCSS]: rowIndex === 0,
                [dataTableV2LastHeaderRowCSS]: rowIndex === rows.length - 1,
              },
            )}
          />
        )),
      )}
    </>
  );
}
DataTableV2Header.displayName = 'DataTableV2Header';
